from fastmcp import Server


def create_openapi_mcp_server(spec: dict[str, Any], client: httpx.AsyncClient) -> Server:
    """Generate an MCP server from an OpenAPI 3.0 specification."""

    server = Server("openapi")

    for path_pattern, path_item in spec.get("paths", {}).items():
        for method_name, operation in path_item.items():
            if method_name not in {"get", "post", "put", "patch", "delete", "head", "options"}:
                continue

            operation_id = operation.get("operationId") or f"{method_name}{path_pattern.translate(str.maketrans('{}/', '___'))}"
            summary = operation.get("summary", "")
            description = operation.get("description", "")
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            # Build input schema
            properties = {}
            required = []

            for param in parameters:
                param_name = param.get("name")
                param_schema = param.get("schema", {})

                properties[param_name] = {
                    "type": param_schema.get("type", "string"),
                    "description": param.get("description", "")
                }

                if param.get("required", False):
                    required.append(param_name)

            if request_body:
                properties["body"] = {
                    "type": "string",
                    "description": "Request body as JSON string"
                }
                if request_body.get("required", False):
                    required.append("body")

            input_schema = {
                "type": "object",
                "properties": properties,
                "required": required
            }

            # Create handler with proper closure
            def create_handler(path, method, params_list):
                async def execute(**kwargs) -> str:
                    url = path
                    query_params = {}
                    headers = {}
                    json_body = None

                    # Process parameters
                    for param in params_list:
                        name = param.get("name")
                        value = kwargs.get(name)

                        if value is None:
                            continue

                        location = param.get("in", "query")
                        if location == "path":
                            url = url.replace(f"{{{name}}}", str(value))
                        elif location == "query":
                            query_params[name] = value
                        elif location == "header":
                            headers[name] = value

                    # Handle request body
                    if "body" in kwargs:
                        try:
                            json_body = json.loads(kwargs["body"])
                        except (json.JSONDecodeError, TypeError):
                            json_body = None

                    # Make the HTTP request
                    response = await client.request(
                        method.upper(),
                        url,
                        params=query_params or None,
                        headers=headers or None,
                        json=json_body if method.lower() in ["post", "put", "patch"] else None
                    )

                    return response.text

                execute.__name__ = operation_id
                execute.__doc__ = summary or description
                return execute

            handler = create_handler(path_pattern, method_name, parameters)

            # Register the tool with the server
            server.add_tool(
                handler,
                name=operation_id,
                description=summary or description or f"{method_name.upper()} {path_pattern}",
                input_schema=input_schema
            )

    return server

